primaryQuery:
run: order_items -> {
  where: shipped_at is not null
  aggregate:
    shipped_lines is count()
    avg_days_to_ship is round(avg(day(created_at::date to shipped_at::date)), 4)
}

verifyQuery:
run: order_items -> {
  where: shipped_at is not null
  group_by: yr is created_at.year
  aggregate:
    n is count()
    gap is sum(day(created_at::date to shipped_at::date))
} -> {
  aggregate:
    shipped_lines is n.sum()
    total_gap is gap.sum()
} -> {
  select:
    shipped_lines
    avg_days_to_ship is round(total_gap / shipped_lines, 4)
}
